-- NovoBharat CONTENT migrated from the original MySQL database.
-- Schema is created by the app (TypeORM synchronize); this file loads DATA only.
-- It TRUNCATEs the content tables first, so it cleanly overrides the seed
-- baseline on a fresh DB. The `users` table is intentionally NOT touched, so the
-- admin account stays as seeded (governed by the ADMIN_PASSWORD you set).
--
-- Load into Render after the Blueprint deploy (External Database URL from the
-- Render dashboard > novobharat-db > Connect):
--   psql "<EXTERNAL_DATABASE_URL>" -f backend/migration/novobharat-data.sql
-- Load into local docker-compose Postgres (adjust port if you remapped it):
--   psql postgresql://novobharat:novobharat@127.0.0.1:5432/novobharat_admin -f backend/migration/novobharat-data.sql

BEGIN;
TRUNCATE TABLE "categories","products","brochures","seo_global","seo_pages","inquiries" RESTART IDENTITY CASCADE;

-- ==== categories ====
SELECT pg_catalog.setval('public.categories_id_seq', 10, true);

-- ==== products ====
SELECT pg_catalog.setval('public.products_id_seq', 31, true);

-- ==== brochures ====
SELECT pg_catalog.setval('public.brochures_id_seq', 1, true);

-- ==== seo_global ====
SELECT pg_catalog.setval('public.seo_global_id_seq', 1, true);

-- ==== seo_pages ====
SELECT pg_catalog.setval('public.seo_pages_id_seq', 3, true);

-- ==== inquiries ====
SELECT pg_catalog.setval('public.inquiries_id_seq', 1, true);
COMMIT;
